-- Simple subqueries in FROM merge into the query that reads them, as in
-- PostgreSQL's pull_up_subqueries: outer filters run before the subquery's
-- output expressions, an output nothing reads is never computed, and outer
-- WHERE conjuncts move into subqueries that stay in place. HAVING conjuncts
-- without aggregates filter rows before grouping.
CREATE TABLE t (x int, y int, k text);
INSERT INTO t VALUES (0, 1, 'a'), (2, 2, 'b'), (5, 3, 'c');
CREATE TABLE u (x int, z int);
INSERT INTO u VALUES (2, 20), (5, 50);
SELECT * FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> 0 ORDER BY x;
SELECT x FROM (SELECT 10/x AS q, x FROM t) s ORDER BY x;
SELECT count(*) FROM (SELECT 10/x AS q, x FROM t) s;
SELECT s.q, u.z FROM (SELECT 10/x AS q, x FROM t) s JOIN u ON s.x = u.x ORDER BY 1;
SELECT s.q, u.z FROM u JOIN (SELECT 10/x AS q, x FROM t) s ON s.x = u.x ORDER BY 1;
SELECT s.q FROM u, (SELECT 10/x AS q, x FROM t) s WHERE s.x = u.x ORDER BY 1;
SELECT * FROM (SELECT CASE WHEN x = 0 THEN 'zero' ELSE (10/x)::text END AS c, x FROM t) s WHERE x > 1 ORDER BY x;
SELECT * FROM (SELECT 10/x AS q, x FROM t WHERE y > 1) s ORDER BY x;
SELECT * FROM (SELECT * FROM (SELECT 10/x AS q, x FROM t) a) b WHERE x <> 0 ORDER BY x;
CREATE VIEW v AS SELECT 10/x AS q, x, k FROM t;
SELECT * FROM v WHERE x <> 0 ORDER BY x;
SELECT k FROM v ORDER BY k;
SELECT v.q, u.z FROM v JOIN u USING (x) ORDER BY 1;
SELECT * FROM t, LATERAL (SELECT 10/t.x AS q) s WHERE t.x <> 0 ORDER BY t.x;
SELECT * FROM t, LATERAL (SELECT 10/t.x AS q FROM u WHERE u.x = t.x) s ORDER BY t.x;
SELECT * FROM t LEFT JOIN (SELECT 10/x AS q, x FROM u) s ON s.x = t.x ORDER BY t.x;
SELECT t.x, s.one FROM t LEFT JOIN (SELECT 1 AS one, x FROM u) s ON s.x = t.x ORDER BY t.x;
SELECT * FROM (SELECT 10/x AS q, x FROM t) s WHERE q > 1 AND x <> 0 ORDER BY x;
SELECT * FROM (SELECT DISTINCT 10/x AS q, x FROM t) s WHERE x <> 0 ORDER BY x;
SELECT * FROM (SELECT 10/x AS q, x FROM t ORDER BY x) s WHERE x <> 0 ORDER BY x;
SELECT * FROM (SELECT 10/x AS q, x FROM t LIMIT 10) s WHERE x <> 0 ORDER BY x;
SELECT * FROM (SELECT x, sum(10/x) AS q FROM t GROUP BY x) s WHERE x <> 0 ORDER BY x;
SELECT * FROM (SELECT 10/x AS q, x FROM t UNION ALL SELECT 1, 1) s WHERE x <> 0 ORDER BY x;
SELECT * FROM (SELECT 'lit' AS l, x FROM t) s WHERE x <> 0 ORDER BY x;
SELECT pg_typeof(l) FROM (SELECT 'lit' AS l, x FROM t) s LIMIT 1;
SELECT * FROM (SELECT x AS a, 10/x AS b FROM t) s(c, d) WHERE c <> 0 ORDER BY c;
SELECT s FROM (SELECT 10/x AS q, x FROM t WHERE x <> 0) s ORDER BY 1;
SELECT s.* FROM (SELECT 10/x AS q, x FROM t) s WHERE s.x <> 0 ORDER BY 2;
SELECT (SELECT max(q) FROM (SELECT 10/x AS q, x FROM t) s WHERE s.x = u.x) FROM u ORDER BY 1;
SELECT * FROM (SELECT 10/x AS q, x FROM t) s WHERE EXISTS (SELECT 1 FROM u WHERE u.x = s.x) ORDER BY x;
SELECT * FROM (SELECT 10/x AS q, x FROM t) s WHERE x IN (SELECT x FROM u) ORDER BY x;
SELECT * FROM (SELECT x FROM t) s, (SELECT 10/z AS w, x FROM u) r WHERE s.x = r.x ORDER BY 1;
SELECT * FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> 0 FOR UPDATE;
SELECT q, count(*) FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> 0 GROUP BY q ORDER BY q;
SELECT x, q FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> 0 ORDER BY q DESC;
SELECT row_number() OVER (ORDER BY x), q FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> 0 ORDER BY 1;
SELECT * FROM (SELECT 10/x AS q, x FROM t) s WHERE s.x <> 0 AND s.q < 100 ORDER BY 2;
SELECT y FROM (SELECT 10/x AS q, x, y FROM t) s WHERE y = 1;
SELECT * FROM (SELECT t.x, u.z, 10/t.x AS q FROM t JOIN u ON t.x = u.x) s ORDER BY 1;
SELECT * FROM (SELECT t.x, u.z, 10/t.x AS q FROM t LEFT JOIN u ON t.x = u.x) s WHERE s.x > 0 ORDER BY 1;
SELECT * FROM (SELECT 10/x AS q FROM t) s ORDER BY 1;
SELECT q::int FROM (SELECT x AS q FROM t) s ORDER BY 1;
SELECT s.x + 1, s.k FROM (SELECT * FROM t) s ORDER BY 1;
SELECT * FROM (SELECT x AS a, y FROM t) s(c) ORDER BY c;
SELECT x AS q FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> 0 ORDER BY q;
SELECT q FROM (SELECT x * 2 AS q, x FROM t) s GROUP BY q ORDER BY q;
SELECT x * 2 AS z FROM (SELECT x FROM t) s GROUP BY z ORDER BY z;
SELECT * FROM u JOIN (SELECT t.x, u2.z, 10/t.x AS q FROM t JOIN u u2 ON t.x = u2.x) s ON s.x = u.x ORDER BY 1;
SELECT * FROM u, (SELECT t.x, 10/t.x AS q FROM t, u u2 WHERE t.x = u2.x) s WHERE s.x = u.x ORDER BY 1;
SELECT (SELECT count(*) FROM u WHERE u.x = s.x) AS c, s.q FROM (SELECT 10/x AS q, x FROM t WHERE x > 0) s ORDER BY 2;
SELECT s.x, (SELECT max(x) FROM u WHERE u.z > s.x) FROM (SELECT x FROM t) s ORDER BY 1;
SELECT * FROM (SELECT x FROM t) s WHERE x IN (SELECT x FROM u WHERE z > 10) ORDER BY 1;
SELECT x FROM (SELECT x FROM t) t ORDER BY 1;
SELECT t.x FROM (SELECT x FROM t) t ORDER BY 1;
SELECT * FROM (SELECT x FROM t) a, (SELECT x FROM t) b WHERE a.x = b.x ORDER BY 1;
SELECT * FROM (SELECT x FROM t) a JOIN (SELECT x FROM u) b ON a.x = b.x ORDER BY 1;
SELECT k, l FROM (SELECT k, 'lit' AS l FROM t) s WHERE l = 'lit' ORDER BY 1;
SELECT pg_typeof(l), pg_typeof(n) FROM (SELECT 'lit' AS l, NULL AS n FROM t) s LIMIT 1;
SELECT l || 'x' FROM (SELECT 'lit' AS l FROM t) s LIMIT 1;
SELECT * FROM (SELECT x, y FROM t WHERE x > 0) s WHERE y < 3 ORDER BY 1;
SELECT count(*) FROM (SELECT * FROM t) s;
SELECT count(*), sum(q) FROM (SELECT 10/x AS q FROM t WHERE x <> 0) s;
SELECT DISTINCT s.k FROM (SELECT k FROM t) s ORDER BY 1;
SELECT * FROM (SELECT x, row_number() OVER (ORDER BY x) AS rn FROM t) s WHERE rn > 1 ORDER BY 1;
SELECT * FROM (SELECT x, row_number() OVER (PARTITION BY x ORDER BY y) AS rn FROM t) s WHERE x <> 0 ORDER BY 1;
SELECT * FROM (SELECT x, generate_series(1, 2) AS g FROM t) s WHERE x <> 0 ORDER BY 1, 2;
SELECT * FROM (SELECT x, 10/x AS q FROM t) s LEFT JOIN u ON u.x = s.x WHERE s.x > 0 ORDER BY 1;
SELECT * FROM (SELECT x, 10/x AS q FROM t) s RIGHT JOIN u ON u.x = s.x ORDER BY 1;
SELECT * FROM (SELECT x, 10/x AS q FROM t) s FULL JOIN u ON u.x = s.x ORDER BY 1;
SELECT * FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> 0 FOR UPDATE OF s;
SELECT * FROM (SELECT * FROM (SELECT x, 10/x AS q FROM t) a WHERE x > 0) b ORDER BY 1;
WITH c AS (SELECT 10/x AS q, x FROM t) SELECT * FROM c WHERE x <> 0 ORDER BY 2;
WITH c AS MATERIALIZED (SELECT 10/x AS q, x FROM t) SELECT * FROM c WHERE x <> 0 ORDER BY 2;
SELECT s FROM (SELECT x FROM t) s ORDER BY 1;
SELECT s.* FROM (SELECT x, k FROM t) s ORDER BY 1;
SELECT (s).x FROM (SELECT x FROM t) s ORDER BY 1;
SELECT row_to_json(s) FROM (SELECT x FROM t) s ORDER BY 1;
SELECT * FROM (SELECT x FROM t) s WHERE nonexist > 0;
SELECT s.nonexist FROM (SELECT x FROM t) s;
SELECT * FROM (SELECT x FROM t) s, (SELECT x FROM u) r WHERE x > 0;
SELECT y FROM (SELECT x FROM t) s;
SELECT * FROM (SELECT x FROM t) s JOIN u USING (x) ORDER BY 1;
SELECT * FROM (SELECT x, 10/x AS q FROM t) s NATURAL JOIN u ORDER BY 1;
PREPARE p1(int) AS SELECT * FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> $1 ORDER BY 2;
EXECUTE p1(0);
SELECT * FROM t WHERE x IN (SELECT x FROM (SELECT x, 10/x AS q FROM u) s WHERE q > 0) ORDER BY 1;
SELECT * FROM (VALUES (1), (0)) v(a), LATERAL (SELECT 10/a AS q) s WHERE a <> 0;
SELECT * FROM generate_series(0, 2) g, LATERAL (SELECT 10/g AS q) s WHERE g <> 0;
SELECT * FROM (SELECT 10/g AS q, g FROM generate_series(0, 2) g) s WHERE g <> 0;
UPDATE t SET y = y WHERE x IN (SELECT x FROM (SELECT 10/x AS q, x FROM t) s WHERE x <> 0);
DELETE FROM u WHERE x IN (SELECT x FROM (SELECT 10/x AS q, x FROM t) s WHERE x = 99);
SELECT * FROM (SELECT x, 10/x AS q FROM t WHERE x > 0) s JOIN u USING (x) ORDER BY 1;
SELECT x, q, z FROM (SELECT x, 10/x AS q FROM t) s JOIN u USING (x) ORDER BY 1;
SELECT * FROM u LEFT JOIN (SELECT x, 10/x AS q FROM t) s USING (x) ORDER BY 1;
SELECT * FROM (SELECT x, 10/x AS q FROM t) s RIGHT JOIN u USING (x) ORDER BY 1;
SELECT * FROM (SELECT x::bigint AS x, 10/x AS q FROM t) s JOIN u USING (x) ORDER BY 1;
SELECT x FROM (SELECT x, 10/x AS q FROM t) s JOIN u USING (x) JOIN (SELECT x, 1 AS one FROM u) r USING (x) ORDER BY 1;
SELECT * FROM (SELECT x, 10/x AS q FROM t) s JOIN u USING (x) AS j WHERE j.x > 0 ORDER BY 1;
SELECT * FROM t LEFT JOIN (SELECT x, 10/x AS q FROM u WHERE z > 20) s ON s.x = t.x ORDER BY 1;
SELECT t.x, s.one FROM t LEFT JOIN (SELECT 1 AS one, x FROM u) s ON s.x = t.x ORDER BY 1;
SELECT * FROM (SELECT x, 10/x AS q FROM t WHERE x > 0) s RIGHT JOIN u ON u.x = s.x ORDER BY 3;
SELECT * FROM (SELECT x, 10/x AS q FROM t) s CROSS JOIN (SELECT 1 AS c) one WHERE s.x <> 0 ORDER BY 1;
SELECT * FROM (SELECT 1 AS c) one, (SELECT x, 10/x AS q FROM t) s WHERE s.x <> 0 ORDER BY 2;
SELECT * FROM (SELECT 1 AS c WHERE false) one, t ORDER BY 2;
SELECT * FROM (SELECT 1 AS c) one LEFT JOIN t ON t.x = one.c ORDER BY 2;
SELECT c FROM (SELECT 1 AS c) one;
SELECT c, count(*) FROM (SELECT 1 AS c) one GROUP BY c;
SELECT x, sum(10/x) FROM t GROUP BY x HAVING x <> 0 ORDER BY 1;
SELECT x, sum(10/x) FROM t GROUP BY x HAVING x <> 0 AND count(*) > 0 ORDER BY 1;
SELECT sum(10/x) FROM t HAVING false;
SELECT x * 2 AS z FROM t GROUP BY z ORDER BY z;
SELECT x AS z, y AS z FROM t GROUP BY z;
SELECT upper(k) FROM t GROUP BY upper ORDER BY 1;
SELECT 1 AS z GROUP BY z;
